using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using StockManagement.Data;using StockManagement.Models;using StockManagement.Services;
namespace StockManagement.Controllers;[Authorize(Roles=Roles.Admin+","+Roles.Manager+","+Roles.Staff)] public class SalesController:Controller{readonly ApplicationDbContext _db;readonly AuditService _audit;public SalesController(ApplicationDbContext db,AuditService audit){_db=db;_audit=audit;}public IActionResult Index()=>View(_db.Sales.Include(x=>x.Customer).OrderByDescending(x=>x.SaleDate).ToList());public IActionResult Create(){ViewBag.Products=_db.Products.Where(x=>x.Status=="Active").OrderBy(x=>x.Name).ToList();ViewBag.Customers=_db.Customers.OrderBy(x=>x.Name).ToList();return View(new SaleCreateVm());}[HttpPost,ValidateAntiForgeryToken]public IActionResult Create(SaleCreateVm vm){ViewBag.Products=_db.Products.Where(x=>x.Status=="Active").OrderBy(x=>x.Name).ToList();ViewBag.Customers=_db.Customers.OrderBy(x=>x.Name).ToList();var lines=vm.Lines.Where(x=>x.ProductId>0&&x.Quantity>0).ToList();if(!lines.Any()){ModelState.AddModelError("","Add at least one product.");return View(vm);}using var tx=_db.Database.BeginTransaction();try{var sale=new Sale{CustomerId=vm.CustomerId,InvoiceNo="INV-"+DateTime.Now.ToString("yyyyMMddHHmmss")};foreach(var l in lines){var p=_db.Products.Find(l.ProductId)??throw new Exception("Product not found");if(p.CurrentStock<l.Quantity)throw new Exception($"Insufficient stock for {p.Name}.");var price=l.UnitPrice>0?l.UnitPrice:p.UnitPrice;sale.Details.Add(new SaleDetail{ProductId=p.Id,Quantity=l.Quantity,UnitPrice=price});p.CurrentStock-=l.Quantity;}sale.TotalAmount=sale.Details.Sum(x=>x.Quantity*x.UnitPrice);_db.Sales.Add(sale);_db.SaveChanges();tx.Commit();_audit.Add("Sale","Create",$"Sale {sale.InvoiceNo} created for {sale.TotalAmount:N2}",User.Identity?.Name??"System");TempData["Success"]=$"Sale {sale.InvoiceNo} created successfully.";return RedirectToAction(nameof(Index));}catch(Exception ex){tx.Rollback();ModelState.AddModelError("",ex.Message);return View(vm);}}
public IActionResult Details(int id){var s=_db.Sales.Include(x=>x.Customer).Include(x=>x.Details).ThenInclude(x=>x.Product).FirstOrDefault(x=>x.Id==id);return s==null?NotFound():View(s);}}
